-- Shared category tree for the Services and Products pages.
-- Structure changes are additive (new columns; slug uniqueness moves from global to per-parent).
-- Data changes create/move categories and re-home products; nothing is deleted.
-- DropIndex
DROP INDEX "Category_slug_key";

-- AlterTable
ALTER TABLE "Category" ADD COLUMN     "content" TEXT,
ADD COLUMN     "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
ADD COLUMN     "imageAlt" TEXT,
ADD COLUMN     "imageKey" TEXT,
ADD COLUMN     "isVisible" BOOLEAN NOT NULL DEFAULT true,
ADD COLUMN     "priceFromMinor" INTEGER,
ADD COLUMN     "priceUnit" TEXT,
ADD COLUMN     "seoDescription" TEXT,
ADD COLUMN     "seoTitle" TEXT,
ADD COLUMN     "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- CreateIndex
CREATE INDEX "Category_parentId_sortOrder_idx" ON "Category"("parentId", "sortOrder");

-- CreateIndex
CREATE UNIQUE INDEX "Category_parentId_slug_key" ON "Category"("parentId", "slug");



-- ─── Data: the shared category tree (generated by scripts/generate-taxonomy-sql.ts) ───

-- Finds a category by parent + slug or creates it. Text is filled in only for categories
-- not yet edited in the new system (content IS NULL), so admin edits are never overwritten.
CREATE OR REPLACE FUNCTION pg_temp.mp_ensure_cat(p_parent text, p_slug text, p_name text, p_short text, p_content text, p_unit text, p_sort int)
RETURNS text LANGUAGE plpgsql AS $fn$
DECLARE v_id text;
BEGIN
  SELECT id INTO v_id FROM "Category" WHERE slug = p_slug AND "parentId" IS NOT DISTINCT FROM p_parent LIMIT 1;
  IF v_id IS NULL THEN
    v_id := 'cat_' || substr(md5(coalesce(p_parent, '') || '/' || p_slug), 1, 20);
    INSERT INTO "Category" (id, name, slug, description, content, "priceUnit", "sortOrder", "parentId", "isVisible", "createdAt", "updatedAt")
    VALUES (v_id, p_name, p_slug, p_short, p_content, p_unit, p_sort, p_parent, true, now(), now());
  ELSE
    UPDATE "Category"
    SET name = p_name, description = p_short, content = p_content, "priceUnit" = coalesce("priceUnit", p_unit), "sortOrder" = p_sort, "updatedAt" = now()
    WHERE id = v_id AND content IS NULL;
  END IF;
  RETURN v_id;
END $fn$;

DO $mig$
DECLARE
  m_board_maker text; m_offset_printing text; m_digital_printing text; m_customized_printing text; c1 text; c2 text; c3 text; c4 text; c5 text; c6 text; c7 text; c8 text; c9 text; c10 text; c11 text; c12 text; c13 text; c14 text; c15 text; c16 text; c17 text; c18 text; c19 text; c20 text; c21 text; c22 text; c23 text; c24 text; c25 text; c26 text; c27 text; c28 text; c29 text; c30 text; c31 text; c32 text; c33 text; c34 text; c35 text; c36 text; c37 text; c38 text; c39 text; c40 text; c41 text; c42 text; c43 text; c44 text; c45 text; c46 text; c47 text; c48 text; c49 text; c50 text; c51 text; c52 text; c53 text; c54 text; c55 text; c56 text; c57 text; c58 text; c59 text; c60 text; c61 text; c62 text; c63 text; c64 text; c65 text; c66 text; c67 text; c68 text; c69 text; c70 text; c71 text; c72 text; c73 text; c74 text; c75 text; c76 text; c77 text; c78 text; c79 text; c80 text; c81 text; c82 text; c83 text; c84 text; c85 text; c86 text; c87 text; c88 text; c89 text; c90 text; c91 text; c92 text; c93 text; c94 text; c95 text; c96 text; c97 text; c98 text; c99 text; c100 text; c101 text; c102 text; c103 text; c104 text; c105 text; c106 text; c107 text; c108 text; c109 text; c110 text; c111 text; c112 text; c113 text; c114 text; c115 text; c116 text; c117 text; c118 text; c119 text; c120 text;
BEGIN
  m_board_maker := pg_temp.mp_ensure_cat(NULL, 'board-maker', 'Board Maker', 'Custom shop signs and sign boards in Lahore: backlit, front-lit and 3D boards designed, made and installed for your business.', 'Your sign board is often the first thing a customer sees, so it has to be clear, bright and built to last. Mix Print Design makes custom sign boards in Lahore for shops, clinics, restaurants, schools, offices and showrooms across Pakistan.

Choose a backlit sign board that glows evenly at night, an economical front-lit board lit from above, or a premium 3D sign board with raised letters in acrylic, aluminium or stainless steel. Our designers can prepare the artwork from your logo, show you a proof for approval, and suggest the right size and material for your location and budget.

Every board is made to your measurements. Tell us the width, height, location and the look you want, and we will send you a quote. Visit us on Raiwind Road, Lahore, or message us on WhatsApp with a photo of your shop front for quick advice.', NULL, 0);
  m_offset_printing := pg_temp.mp_ensure_cat(NULL, 'offset-printing', 'Offset Printing', 'High-quality offset printing in Lahore: business cards, brochures, flyers, letterheads, bill books, packaging and more.', 'Offset printing is the best choice when you need sharp, consistent colour across hundreds or thousands of copies. Mix Print Design offers offset printing in Lahore for businesses, schools, clinics, events and brands across Pakistan.

From business cards and brochures to letterheads, envelopes, bill books, calendars, wedding cards and product packaging, we print on a wide range of papers and boards with finishes such as matte or gloss lamination, spot UV, foil and embossing. Larger runs keep the cost per piece low, which makes offset ideal for stationery and marketing material you use every day.

Browse the categories below to see the options, or send us your artwork, quantity and paper preference for a quote. Our design team can create or fix your artwork, and nothing is printed until you approve the proof.', NULL, 1);
  m_digital_printing := pg_temp.mp_ensure_cat(NULL, 'digital-printing', 'Digital Printing', 'Digital and large-format printing in Lahore: flex, panaflex, vinyl, one-way vision, canvas, standees and backlit film.', 'Digital printing is ideal for large formats, short runs and fast turnarounds. Mix Print Design offers digital and large-format printing in Lahore for shop signage, events, exhibitions, offices and homes across Pakistan.

Print vibrant banners on China flex, Star flex or premium Korean flex, branded panaflex for sign boards, vinyl stickers and one-way vision for windows and vehicles, canvas prints for décor, and roll-up standees for exhibitions. Large-format jobs are usually priced per square foot, so you only pay for the size you need.

Choose a category below to compare materials, or send us the size, quantity and location for a quote. Our designers can prepare print-ready artwork at the right resolution, and you approve the proof before printing.', NULL, 2);
  m_customized_printing := pg_temp.mp_ensure_cat(NULL, 'customized-printing', 'Customized Printing', 'Customized printing in Lahore: mugs, pens, keychains, T-shirts, caps, shields, acrylic name plates and laser engraving.', 'Customized printing puts your name, logo or message on everyday items that people keep and use. Mix Print Design offers customized printing in Lahore on mugs, pens, keychains, photo frames, T-shirts, caps and safety jackets, plus laser engraving, acrylic name plates and award shields.

Companies order branded giveaways for events and staff, schools order shields and souvenirs, and families order personalised gifts for birthdays, weddings and Eid. Many items can be personalised one by one with different names or photos.

Choose an item below, or send us your idea, quantity and deadline. Our designers can prepare the artwork, and you approve the proof before we produce your order. We deliver across Pakistan.', NULL, 3);

  -- Move the original product categories under their main service
  UPDATE "Category" SET "parentId" = m_offset_printing, slug = 'business-cards' WHERE "parentId" IS NULL AND slug = 'business-cards' AND NOT EXISTS (SELECT 1 FROM "Category" WHERE "parentId" = m_offset_printing AND slug = 'business-cards');
  UPDATE "Category" SET "parentId" = m_offset_printing, slug = 'flyers-leaflets' WHERE "parentId" IS NULL AND slug = 'marketing' AND NOT EXISTS (SELECT 1 FROM "Category" WHERE "parentId" = m_offset_printing AND slug = 'flyers-leaflets');
  UPDATE "Category" SET "parentId" = m_offset_printing, slug = 'stickers-labels' WHERE "parentId" IS NULL AND slug = 'stickers-labels' AND NOT EXISTS (SELECT 1 FROM "Category" WHERE "parentId" = m_offset_printing AND slug = 'stickers-labels');
  UPDATE "Category" SET "parentId" = m_offset_printing, slug = 'packaging-boxes' WHERE "parentId" IS NULL AND slug = 'packaging' AND NOT EXISTS (SELECT 1 FROM "Category" WHERE "parentId" = m_offset_printing AND slug = 'packaging-boxes');
  UPDATE "Category" SET "parentId" = m_offset_printing, slug = 'letterheads' WHERE "parentId" IS NULL AND slug = 'stationery' AND NOT EXISTS (SELECT 1 FROM "Category" WHERE "parentId" = m_offset_printing AND slug = 'letterheads');
  UPDATE "Category" SET "parentId" = m_digital_printing, slug = 'standees-roll-up-banners' WHERE "parentId" IS NULL AND slug = 'large-format' AND NOT EXISTS (SELECT 1 FROM "Category" WHERE "parentId" = m_digital_printing AND slug = 'standees-roll-up-banners');

  -- Categories and sub-categories
  c1 := pg_temp.mp_ensure_cat(m_board_maker, 'backlit-sign-board', 'Backlit Sign Board', 'Illuminated backlit sign boards that light up your shop name evenly, day and night. Made to size in Lahore.', 'A backlit sign board is lit from inside, so your name and logo glow evenly after sunset and stay visible from a distance. It is the most popular choice for shop fronts, pharmacies, restaurants, salons and showrooms in Lahore.

Mix Print Design prints your artwork on translucent backlit media and fits it to a sturdy frame with LED lighting behind it. Different media qualities give different brightness, colour depth and lifespan, so we can match the board to your budget and how long you want it to last.

Send us your shop front width and height, or a photo, and we will suggest the right size and quality. Our designers can also refresh your logo and layout before printing, and you approve a proof before anything is made.', NULL, 0); -- board-maker/backlit-sign-board
  c2 := pg_temp.mp_ensure_cat(m_board_maker, 'front-lit-sign-board', 'Front-lit Sign Board', 'Economical front-lit sign boards with spotlights mounted above. Clear, durable shop signs made to measure in Lahore.', 'A front-lit sign board is printed on durable flex and lit by spotlights mounted in front of or above the board. It is an affordable, practical choice for large shop fronts, markets, warehouses, schools and roadside signage across Lahore and Pakistan.

Because the light falls on the surface, front-lit boards show sharp, full-colour graphics and work well in very large sizes. We print your design, stretch it on a strong frame and can arrange suitable lighting for night visibility.

Tell us the board size and where it will be installed, and we will recommend the right flex quality and frame. You approve the design proof before production, and our team can help with the layout if you only have a logo or a rough idea.', NULL, 1); -- board-maker/front-lit-sign-board
  c3 := pg_temp.mp_ensure_cat(m_board_maker, '3d-sign-board', '3D Sign Board', 'Premium 3D sign boards with raised letters and logos in acrylic, aluminium, stainless steel and more. Made in Lahore.', 'A 3D sign board uses raised letters and logos that stand out from the wall, giving your business a premium, modern look. 3D signs are popular for offices, reception areas, brand showrooms, restaurants and boutiques in Lahore and across Pakistan.

Mix Print Design makes 3D signs in a range of styles and materials, from simple cut-letter signs to acrylic logo boards, glittering signs, aluminium letters and polished stainless steel. Many styles can be lit with LEDs for a glowing halo or face-lit effect at night.

Choose a style below to see the options, or send us your logo and wall size for a quote. We prepare a scaled proof so you can see exactly how the sign will look before it is made.', NULL, 2); -- board-maker/3d-sign-board
  c4 := pg_temp.mp_ensure_cat(c3, 'simple-sign', 'Simple Sign', 'Clean, affordable signs with cut lettering, ideal for small shops and offices in Lahore.', 'A simple sign is the most affordable way to put your name on the wall with a neat, professional finish. Cut letters or a flat panel with your name and logo suit small shops, home businesses, clinics and office doors. It is quick to produce, easy to install and can be upgraded later to a lit or 3D style. Share your name, logo and the space available, and we will suggest a size and colour that reads clearly from the street.', NULL, 0); -- board-maker/3d-sign-board/simple-sign
  c5 := pg_temp.mp_ensure_cat(c3, '2d-sign', '2D Sign', 'Flat 2D signs with crisp printed or cut graphics for walls, doors and shop fronts.', 'A 2D sign keeps your graphics flat on a single panel, giving a clean and modern look at a lower cost than raised letters. It works well for reception walls, door signs, directional signs and shop fronts where the sign is viewed from close range. We can combine printed panels with cut vinyl or acrylic details, and you approve the design proof before production. Tell us the size and location for a quote.', NULL, 1); -- board-maker/3d-sign-board/2d-sign
  c6 := pg_temp.mp_ensure_cat(c3, '3d-sign', '3D Sign', 'Raised 3D letters and logos that add depth and a premium feel to your brand.', 'A 3D sign uses individually made raised letters and logo shapes that stand off the wall to create depth and shadow. It gives showrooms, offices and restaurants a premium look that is noticed from a distance. Letters can be finished in different colours and materials and lit with LEDs for a front-lit or halo glow at night. Send us your logo and wall measurements and we will prepare a scaled preview and quote.', NULL, 2); -- board-maker/3d-sign-board/3d-sign
  c7 := pg_temp.mp_ensure_cat(c3, 'acrylic-logo-board', 'Acrylic + Logo Board', 'Glossy acrylic boards with your logo for receptions, offices and counters.', 'An acrylic logo board combines a glossy acrylic panel with your logo and name, often mounted on stand-off fittings for a floating effect. It is a favourite for reception areas, clinic counters and office entrances because it looks clean and premium indoors. Logos can be printed, cut in coloured acrylic or raised for extra depth. Share your logo and preferred size, and we will suggest the right acrylic thickness and finish.', NULL, 3); -- board-maker/3d-sign-board/acrylic-logo-board
  c8 := pg_temp.mp_ensure_cat(c3, 'glitter-sign', 'Glitter Sign', 'Eye-catching glitter signs that sparkle, ideal for salons, boutiques and events.', 'A glitter sign adds sparkle to your name or logo and catches the light from every angle. It is a popular choice for beauty salons, bridal boutiques, gift shops, cafés and event backdrops where a playful, glamorous look fits the brand. Glitter finishes can be combined with acrylic or 3D letters and selected colours. Tell us your logo, colours and size, and we will show you a design proof before making the sign.', NULL, 4); -- board-maker/3d-sign-board/glitter-sign
  c9 := pg_temp.mp_ensure_cat(c3, 'aluminium-sign', 'Aluminium Sign', 'Durable aluminium signs and letters with a sleek metallic finish for indoor and outdoor use.', 'Aluminium signs are lightweight, strong and weather resistant, making them suitable for outdoor shop fronts as well as modern interiors. Brushed and painted finishes give a sleek, professional look for offices, factories, showrooms and building entrances across Lahore. Aluminium can be used for flat panels or raised letters, with or without LED lighting. Send us your design and installation details for a quote.', NULL, 5); -- board-maker/3d-sign-board/aluminium-sign
  c10 := pg_temp.mp_ensure_cat(c3, 'ss-stainless-steel-sign', 'SS (Stainless Steel) Sign', 'Premium stainless steel (SS) letters in silver, gold or rose gold finishes for a luxury look.', 'Stainless steel (SS) signs give the most premium finish for corporate offices, hotels, jewellers and high-end showrooms. Letters can be polished or brushed in silver, gold or rose-gold tones and are highly durable outdoors. SS letters can be lit from behind for an elegant halo effect at night. Share your logo, wall size and preferred finish, and we will prepare a scaled preview and quote before production.', NULL, 6); -- board-maker/3d-sign-board/ss-stainless-steel-sign
  c11 := pg_temp.mp_ensure_cat(m_offset_printing, 'business-cards', 'Business Cards', 'Business card printing in Lahore: matte, gloss, laminated, spot UV, foil, embossed and premium cards.', 'A good business card makes a strong first impression and keeps your contact details in your customer''s pocket. Mix Print Design prints business cards in Lahore in a wide range of papers and finishes, from simple matte cards to premium laminated, spot UV, foil and embossed designs.

Choose a finish below to compare options. Standard cards suit everyday networking, while textured, kraft, transparent and specialty cards help creative brands, boutiques and professionals stand out. Single or double-sided printing is available, and round corners add a modern touch.

Upload your own design or ask our designers to create one from your logo. We send a digital proof for approval before printing, and we deliver across Pakistan. Larger quantities lower the price per card, so ask for a quote for your team or multiple names.', NULL, 0); -- offset-printing/business-cards
  c12 := pg_temp.mp_ensure_cat(c11, 'matte', 'Matte Business Cards', 'Classic matte business cards with a smooth, non-reflective finish that is easy to write on.', 'Matte business cards have a soft, non-reflective surface that looks professional and is easy to read in any light. They are a reliable everyday choice for professionals, shops and offices in Lahore. Matte card is also easy to write on, which is useful for appointment cards and notes. Pair with a clean design and dark text for the best result.', NULL, 0); -- offset-printing/business-cards/matte
  c13 := pg_temp.mp_ensure_cat(c11, 'shine-gloss', 'Shine (Gloss) Business Cards', 'Glossy business cards with vivid, shiny colours that make photos and logos pop.', 'Shine or gloss business cards have a glossy coating that makes colours brighter and images sharper. They suit brands with bold colours, photos or product images, such as restaurants, salons and retail shops. The shiny finish catches the light and gives the card a lively feel. Ask us to check your design so colours print as vividly as possible.', NULL, 1); -- offset-printing/business-cards/shine-gloss
  c14 := pg_temp.mp_ensure_cat(c11, 'matte-lamination', 'Matte Lamination Business Cards', 'Thick cards with a soft-touch matte lamination for a premium, durable feel.', 'Matte lamination adds a thin protective film to both sides of the card, giving it a smooth, velvety feel and extra durability. Laminated cards resist scuffs, moisture and bending, so they look good for longer. This finish is popular with corporate offices, consultants and premium brands in Lahore that want a subtle, high-end look.', NULL, 2); -- offset-printing/business-cards/matte-lamination
  c15 := pg_temp.mp_ensure_cat(c11, 'gloss-lamination', 'Gloss Lamination Business Cards', 'Durable gloss-laminated cards with rich, shiny colours and strong protection.', 'Gloss lamination seals the card with a shiny film that deepens colours and protects against moisture and wear. It is a great choice for cards with strong colours or photographs and for businesses whose cards are handled often. The result is a sturdy, vibrant card that keeps its look in wallets and pockets.', NULL, 3); -- offset-printing/business-cards/gloss-lamination
  c16 := pg_temp.mp_ensure_cat(c11, 'matte-back-side', 'Matte Back Side Business Cards', 'Cards with a glossy front and matte back, so the back is easy to write on.', 'These cards combine a finished front with a matte back side, giving you an attractive face and a writable reverse. They are ideal for appointment cards, loyalty cards and doctors'' or salon cards where staff write dates or notes on the back. Share how you plan to use the card and we will suggest the best combination.', NULL, 4); -- offset-printing/business-cards/matte-back-side
  c17 := pg_temp.mp_ensure_cat(c11, 'single-colour', 'Single Colour Business Cards', 'Economical single-colour business cards for large quantities and simple designs.', 'Single colour business cards print your design in one ink colour, keeping costs low for large quantities. They are practical for staff cards, wholesale shops, events and simple text-based designs. A well-chosen ink colour on quality card still looks clean and professional. Ask for a quote if you need cards for many names at once.', NULL, 5); -- offset-printing/business-cards/single-colour
  c18 := pg_temp.mp_ensure_cat(c11, 'round-corner', 'Round Corner Business Cards', 'Business cards with smooth rounded corners for a modern, friendly look.', 'Round corner business cards have gently curved corners that feel comfortable in the hand and look modern. The rounded edges also resist bending and fraying in wallets. This finish suits creative brands, cafés, boutiques and anyone who wants a softer look. It can be combined with lamination and other finishes.', NULL, 6); -- offset-printing/business-cards/round-corner
  c19 := pg_temp.mp_ensure_cat(c11, 'spot-uv', 'Spot UV Business Cards', 'Premium cards with glossy spot UV highlights on your logo or text.', 'Spot UV adds a raised, glossy coating to selected parts of your design, such as the logo or name, on top of a matte card. The contrast between shiny and matte areas creates a premium effect people notice when they hold the card. Spot UV is popular with corporate, real-estate and fashion brands. We help you set up the artwork correctly for the effect.', NULL, 7); -- offset-printing/business-cards/spot-uv
  c20 := pg_temp.mp_ensure_cat(c11, 'embossed', 'Embossed Business Cards', 'Embossed business cards with raised logos or text you can feel.', 'Embossing presses your logo or text up from the card surface, creating a raised design you can see and feel. It gives a classic, luxurious touch that suits law firms, jewellers, hotels and premium brands. Embossing works best on thicker card and simple shapes. Send us your logo and we will advise what will emboss cleanly.', NULL, 8); -- offset-printing/business-cards/embossed
  c21 := pg_temp.mp_ensure_cat(c11, 'foil', 'Foil Business Cards', 'Gold, silver or coloured foil business cards for a luxury finish.', 'Foil stamping applies shiny metallic foil, such as gold, silver or rose gold, to parts of your design. It is one of the most eye-catching finishes and is often combined with matte lamination for a luxury look. Foil cards suit jewellers, wedding planners, boutiques and executives. Share your design and we will mark the areas to be foiled in the proof.', NULL, 9); -- offset-printing/business-cards/foil
  c22 := pg_temp.mp_ensure_cat(c11, 'textured-linen', 'Textured / Linen Business Cards', 'Textured and linen-finish cards with an elegant, tactile feel.', 'Textured and linen business cards have a fine woven pattern you can feel, giving them a classic, crafted character. They suit lawyers, architects, consultants and boutique brands that want a refined, understated card. Simple designs and dark inks look especially elegant on textured stock. Ask us for the available textures and colours.', NULL, 10); -- offset-printing/business-cards/textured-linen
  c23 := pg_temp.mp_ensure_cat(c11, 'kraft', 'Kraft Business Cards', 'Natural brown kraft cards with an earthy, eco-friendly look.', 'Kraft business cards are printed on natural brown paper board for a rustic, eco-friendly feel. They are popular with organic food brands, cafés, handmade products, gift shops and creative studios. Dark or white inks work best on kraft. If you want your brand to feel natural and honest, kraft is a great choice.', NULL, 11); -- offset-printing/business-cards/kraft
  c24 := pg_temp.mp_ensure_cat(c11, 'transparent-plastic', 'Transparent / Plastic Business Cards', 'Clear or frosted plastic business cards that are waterproof and memorable.', 'Transparent and plastic business cards are printed on clear or frosted PVC, making them waterproof, durable and very memorable. They suit tech companies, beauty brands, designers and anyone who wants a card people keep. Designs with strong colours and clear empty space work best. Ask us for samples and options before you order.', NULL, 12); -- offset-printing/business-cards/transparent-plastic
  c25 := pg_temp.mp_ensure_cat(m_offset_printing, 'brochures', 'Brochures', 'Brochure printing in Lahore: bi-fold, tri-fold, Z-fold, gate-fold and saddle-stitched booklets.', 'Brochures present your company, products or services in a format customers can take home and read. Mix Print Design prints brochures in Lahore in popular folds and sizes, with full-colour printing on quality art paper and optional lamination.

Choose a bi-fold for a simple four-page layout, a tri-fold for menus and service lists, a Z-fold or gate-fold for a dramatic reveal, or a saddle-stitched booklet when you need more pages. Schools, hospitals, real-estate projects, manufacturers and restaurants across Pakistan use our brochures for marketing and events.

Send us your content and quantity, or ask our designers to lay out the brochure for you. We send a proof to check text and folding before we print.', NULL, 1); -- offset-printing/brochures
  c26 := pg_temp.mp_ensure_cat(c25, 'bi-fold', 'Bi-fold Brochures', 'Bi-fold brochures folded once into four panels, ideal for company profiles.', 'A bi-fold brochure is folded once to create four panels, giving a clean, book-like layout. It suits company profiles, product introductions, event programmes and price lists. Larger sizes such as A4 folded to A5 give plenty of space for images and text. We can design the layout and print it on your choice of paper.', NULL, 0); -- offset-printing/brochures/bi-fold
  c27 := pg_temp.mp_ensure_cat(c25, 'tri-fold', 'Tri-fold Brochures', 'Classic tri-fold brochures with six panels for menus, services and promotions.', 'Tri-fold brochures are folded twice into three sections, creating six panels that guide readers step by step. They are a favourite for restaurant menus, clinic services, school admissions and promotional handouts. The compact folded size fits easily in stands and envelopes. Share your content and we will arrange it to fold correctly.', NULL, 1); -- offset-printing/brochures/tri-fold
  c28 := pg_temp.mp_ensure_cat(c25, 'z-fold', 'Z-fold Brochures', 'Z-fold brochures that open like an accordion for step-by-step information.', 'A Z-fold brochure folds in a zig-zag pattern, opening like an accordion to reveal information in sequence. It works well for maps, timelines, product ranges and instructions. Z-folds can also open flat to show a wide panoramic image. Our designers can help plan the panel order so the brochure reads naturally.', NULL, 2); -- offset-printing/brochures/z-fold
  c29 := pg_temp.mp_ensure_cat(c25, 'gate-fold', 'Gate-fold Brochures', 'Gate-fold brochures with two panels opening like doors for a dramatic reveal.', 'In a gate-fold brochure the two outer panels fold inward and open like doors to reveal a large central spread. It creates an impressive reveal for product launches, real-estate projects and premium invitations. Gate-folds work best on quality paper with strong imagery. Ask us about sizes and finishes for your project.', NULL, 3); -- offset-printing/brochures/gate-fold
  c30 := pg_temp.mp_ensure_cat(c25, 'booklet-saddle-stitched', 'Booklet / Saddle-stitched', 'Multi-page booklets bound with staples on the spine, for catalogues and guides.', 'Saddle-stitched booklets are folded sheets stapled along the spine, an affordable way to print multi-page documents. They suit catalogues, annual reports, school magazines, guides and event programmes. Page counts are in multiples of four. Send us your page count and quantity, and we will advise on paper and cover options.', NULL, 4); -- offset-printing/brochures/booklet-saddle-stitched
  c31 := pg_temp.mp_ensure_cat(m_offset_printing, 'flyers-leaflets', 'Flyers & Leaflets', 'Flyer and leaflet printing in Lahore in A4, A5 and DL sizes for promotions, menus and events.', 'Flyers and leaflets are one of the most cost-effective ways to promote an offer, event or new business. Mix Print Design prints flyers in Lahore in A4, A5 and DL sizes, single or double-sided, on glossy or matte paper.

Restaurants use them for menus and deals, schools for admissions, shops for sales and political and community groups for campaigns across Pakistan. Large quantities keep the price per flyer low, which makes door-to-door and in-store distribution affordable.

Choose a size below, then send us your artwork or brief. Our designers can create an eye-catching flyer with clear headlines and contact details, and you approve the proof before printing.', NULL, 2); -- offset-printing/flyers-leaflets
  c32 := pg_temp.mp_ensure_cat(c31, 'a4-flyers', 'A4 Flyers', 'Large A4 flyers with plenty of space for menus, notices and detailed offers.', 'A4 flyers give you a full page for detailed information, such as restaurant menus, price lists, notices and event schedules. They are easy to read and suit noticeboards, counters and mail drops. Print on one or both sides, with gloss or matte paper. We can help structure the content so the key message stands out.', NULL, 0); -- offset-printing/flyers-leaflets/a4-flyers
  c33 := pg_temp.mp_ensure_cat(c31, 'a5-flyers', 'A5 Flyers', 'Handy A5 flyers, the most popular size for promotions and handouts.', 'A5 flyers are half the size of A4 and the most popular choice for promotions, handouts and in-store offers. They are easy to carry, cost-effective in large quantities and fit well on counters. Bold headlines and clear contact details make A5 flyers work hard for your business. Ask for a quote by quantity.', NULL, 1); -- offset-printing/flyers-leaflets/a5-flyers
  c34 := pg_temp.mp_ensure_cat(c31, 'dl-leaflets', 'DL Leaflets', 'Slim DL leaflets that fit envelopes and display racks.', 'DL leaflets have a slim, tall shape that fits standard envelopes and leaflet racks. They are ideal for price lists, appointment reminders, tourist information and direct mail. The narrow format encourages short, focused messages. Share your content and we will suggest a clean, readable layout.', NULL, 2); -- offset-printing/flyers-leaflets/dl-leaflets
  c35 := pg_temp.mp_ensure_cat(m_offset_printing, 'letterheads', 'Letterheads', 'Professional letterhead printing in Lahore for offices, schools, clinics and companies.', 'A printed letterhead makes every letter, quotation and invoice look official. Mix Print Design prints letterheads in Lahore for companies, schools, hospitals, law firms and government suppliers across Pakistan.

We print your logo, address and contact details on quality paper that works in office printers, so you can type and print documents on the sheets yourself. Choose single-colour printing for economy, full-colour for logos with many colours, or premium paper for a more impressive feel.

Order letterheads together with envelopes and business cards to keep your stationery consistent. Our designers can create a matching set from your logo, and you approve the proof before we print.', NULL, 3); -- offset-printing/letterheads
  c36 := pg_temp.mp_ensure_cat(c35, 'single-colour-letterheads', 'Single Colour Letterheads', 'Economical one-colour letterheads for everyday office use.', 'Single colour letterheads print your logo and details in one ink, keeping costs low for large quantities. They are practical for daily correspondence, quotations and internal documents. A carefully chosen ink colour still looks crisp and professional. Ask for a quote for bulk office stock.', NULL, 0); -- offset-printing/letterheads/single-colour-letterheads
  c37 := pg_temp.mp_ensure_cat(c35, 'full-colour-letterheads', 'Full Colour Letterheads', 'Full-colour letterheads that reproduce your logo and brand colours accurately.', 'Full colour letterheads reproduce logos with several colours, gradients or photos exactly as designed. They suit brands that want consistent colours across all stationery. Full colour also allows design elements such as footers, watermarks and coloured borders. We check your colours in the proof before printing.', NULL, 1); -- offset-printing/letterheads/full-colour-letterheads
  c38 := pg_temp.mp_ensure_cat(c35, 'premium-paper-letterheads', 'Premium Paper Letterheads', 'Letterheads on thicker, textured or premium paper for an executive feel.', 'Premium paper letterheads use thicker or textured stock that feels substantial in the hand. They suit law firms, consultancies, embassies and executive offices that want correspondence to make a strong impression. Ask us about available papers and whether they suit your office printer.', NULL, 2); -- offset-printing/letterheads/premium-paper-letterheads
  c39 := pg_temp.mp_ensure_cat(m_offset_printing, 'envelopes', 'Envelopes', 'Printed envelopes in Lahore: DL, A4, A5 and window envelopes with your logo and address.', 'Printed envelopes complete your office stationery and make every letter, invoice and invitation look professional. Mix Print Design prints envelopes in Lahore with your logo and return address in popular sizes, including DL, A5 and A4, as well as window envelopes for invoices.

Companies, schools, banks, clinics and wedding planners across Pakistan use our envelopes for correspondence, documents and invitations. Choose the size that fits your letterheads and documents, and match the printing to your business cards and letterheads.

Tell us the size, quantity and design, or let our designers prepare it. You approve the proof before printing, and we can deliver across Pakistan.', NULL, 4); -- offset-printing/envelopes
  c40 := pg_temp.mp_ensure_cat(c39, 'dl-envelopes', 'DL Envelopes', 'Standard DL envelopes for letters folded in three.', 'DL envelopes fit an A4 letter folded into three, making them the standard office envelope for correspondence and invoices. We print your logo and return address for a professional look. They pair perfectly with printed letterheads. Ask for a quote for office quantities.', NULL, 0); -- offset-printing/envelopes/dl-envelopes
  c41 := pg_temp.mp_ensure_cat(c39, 'a4-envelopes', 'A4 Envelopes', 'Large A4 envelopes for documents, certificates and brochures sent flat.', 'A4 envelopes hold documents without folding, which is ideal for certificates, reports, contracts and brochures. Schools, banks and companies use them for official documents. We print your branding on the front for a professional presentation.', NULL, 1); -- offset-printing/envelopes/a4-envelopes
  c42 := pg_temp.mp_ensure_cat(c39, 'a5-envelopes', 'A5 Envelopes', 'Medium A5 envelopes for cards, invitations and folded documents.', 'A5 envelopes suit greeting cards, invitations and A4 sheets folded once. They are popular for events, wedding cards and promotional mailers. Printed branding adds a personal touch. Share your quantity and design for a quote.', NULL, 2); -- offset-printing/envelopes/a5-envelopes
  c43 := pg_temp.mp_ensure_cat(c39, 'window-envelopes', 'Window Envelopes', 'Window envelopes that show the address printed on your invoice or letter.', 'Window envelopes have a clear panel that shows the address printed on the document inside, saving time when sending invoices, bills and statements. They are widely used by utilities, schools and businesses that send regular mail. We print your logo and return address on the front.', NULL, 3); -- offset-printing/envelopes/window-envelopes
  c44 := pg_temp.mp_ensure_cat(m_offset_printing, 'bill-books-invoice-books', 'Bill Books / Invoice Books', 'Bill book and invoice book printing in Lahore with carbonless duplicate and triplicate copies.', 'Bill books and invoice books are essential for shops, wholesalers, workshops, restaurants and service businesses across Pakistan. Mix Print Design prints bill books in Lahore with your business name, logo, address and serial numbering, on carbonless (NCR) paper so every copy is clear without carbon sheets.

Choose duplicate books for a customer copy and an office copy, triplicate books when a third copy is needed, receipt books for payments, or delivery challan books for goods dispatch. Pads are bound with sturdy covers and perforated so pages tear out neatly.

Send us your current bill format or ask our designers to create one. You approve the layout before printing, and we can number each page for easy record keeping.', NULL, 5); -- offset-printing/bill-books-invoice-books
  c45 := pg_temp.mp_ensure_cat(c44, 'duplicate-ncr-bill-books', 'Duplicate (NCR) Bill Books', 'Two-part carbonless bill books with a customer copy and an office copy.', 'Duplicate bill books use two-part carbonless paper, so writing on the top sheet creates a clean copy underneath. The customer takes the original and you keep the copy for records. They suit shops, workshops and service businesses. Pages can be numbered and perforated.', NULL, 0); -- offset-printing/bill-books-invoice-books/duplicate-ncr-bill-books
  c46 := pg_temp.mp_ensure_cat(c44, 'triplicate-ncr-bill-books', 'Triplicate (NCR) Bill Books', 'Three-part carbonless bill books for customer, office and accounts copies.', 'Triplicate bill books produce three copies at once, useful when the customer, the office and the accounts or delivery team each need a copy. They are common with wholesalers, distributors and companies with formal record keeping. We number and bind them to your requirements.', NULL, 1); -- offset-printing/bill-books-invoice-books/triplicate-ncr-bill-books
  c47 := pg_temp.mp_ensure_cat(c44, 'receipt-books', 'Receipt Books', 'Printed receipt books for payments, fees and donations.', 'Receipt books provide a quick, official record for payments such as school fees, rent, donations and service charges. Printed with your name, logo and serial numbers, they help prevent errors and build trust. Choose single, duplicate or triplicate formats.', NULL, 2); -- offset-printing/bill-books-invoice-books/receipt-books
  c48 := pg_temp.mp_ensure_cat(c44, 'delivery-challan-books', 'Delivery Challan Books', 'Delivery challan books to record goods dispatched to customers.', 'Delivery challan books record goods sent to customers, with space for items, quantities and signatures. They are widely used by manufacturers, distributors and suppliers in Pakistan. Carbonless copies keep your dispatch records accurate. Share your format and we will set it up.', NULL, 3); -- offset-printing/bill-books-invoice-books/delivery-challan-books
  c49 := pg_temp.mp_ensure_cat(m_offset_printing, 'files-folders', 'Files & Folders', 'Printed files and presentation folders in Lahore for offices, schools and events.', 'Printed files and folders keep documents organised and present your brand professionally in meetings, admissions and events. Mix Print Design prints presentation folders, file covers and certificate folders in Lahore on sturdy board with your logo and design.

Companies use pocket folders for proposals and press kits, schools and colleges use file covers for admissions and results, and event organisers use certificate folders for awards. Lamination and spot UV can add durability and a premium finish.

Tell us the size, quantity and any pockets or card slots you need. Our designers can create the artwork to match your stationery, and you approve the proof before we print.', NULL, 6); -- offset-printing/files-folders
  c50 := pg_temp.mp_ensure_cat(c49, 'presentation-folders', 'Presentation Folders', 'Pocket folders for proposals, press kits and company profiles.', 'Presentation folders have inside pockets to hold documents, brochures and business cards neatly. They make proposals and company profiles look polished in client meetings. Lamination and spot UV give a premium finish. Ask us about pocket and card-slot options.', NULL, 0); -- offset-printing/files-folders/presentation-folders
  c51 := pg_temp.mp_ensure_cat(c49, 'file-covers', 'File Covers', 'Printed file covers for offices, schools and colleges.', 'Printed file covers protect documents and carry your branding, ideal for schools, colleges, hospitals and offices. They are used for admissions, patient files, reports and internal records. Choose a sturdy board and simple layout for everyday use.', NULL, 1); -- offset-printing/files-folders/file-covers
  c52 := pg_temp.mp_ensure_cat(c49, 'certificate-folders', 'Certificate Folders', 'Elegant folders to present certificates and awards.', 'Certificate folders present certificates, degrees and awards in an elegant cover. Schools, universities, training institutes and companies use them for ceremonies and recognition events. Foil or embossed logos add a formal touch. Share the certificate size for a matching folder.', NULL, 2); -- offset-printing/files-folders/certificate-folders
  c53 := pg_temp.mp_ensure_cat(m_offset_printing, 'stickers-labels', 'Stickers & Labels', 'Sticker and label printing in Lahore: paper, vinyl, die-cut stickers and product labels.', 'Stickers and labels help brand your products, packaging and promotions. Mix Print Design prints stickers and labels in Lahore on paper and vinyl, in sheets or cut to custom shapes, for businesses across Pakistan.

Food and cosmetics brands use product labels with ingredients and barcodes, shops use logo stickers to seal bags and boxes, and marketers use die-cut stickers for giveaways. Waterproof vinyl suits bottles and outdoor use, while paper stickers are economical for packaging and indoor labels.

Tell us the size, shape, material and quantity, and send your artwork or ask our designers for help. We prepare a proof with cut lines so you can check everything before printing.', NULL, 7); -- offset-printing/stickers-labels
  c54 := pg_temp.mp_ensure_cat(c53, 'paper-stickers', 'Paper Stickers', 'Economical paper stickers for packaging, seals and indoor labels.', 'Paper stickers are an economical way to brand bags, boxes and envelopes or to label products for indoor use. They print sharp colours and are available in sheets or cut to shape. Choose gloss or matte paper. Ideal for large quantities at a low price per sticker.', NULL, 0); -- offset-printing/stickers-labels/paper-stickers
  c55 := pg_temp.mp_ensure_cat(c53, 'vinyl-stickers', 'Vinyl Stickers', 'Durable, waterproof vinyl stickers for bottles, outdoor use and giveaways.', 'Vinyl stickers are waterproof, tear-resistant and suitable for bottles, jars, laptops and outdoor surfaces. They keep colours bright and resist moisture and handling. Choose white, clear or other vinyl types depending on your design. Ask us which vinyl suits your surface.', NULL, 1); -- offset-printing/stickers-labels/vinyl-stickers
  c56 := pg_temp.mp_ensure_cat(c53, 'product-labels', 'Product Labels', 'Custom product labels with branding, ingredients and barcodes.', 'Product labels carry your brand, product details, ingredients and barcodes for food, cosmetics, cleaning products and more. We print them in the size and material that fits your containers. Clear, accurate labels help your products look professional on shop shelves.', NULL, 2); -- offset-printing/stickers-labels/product-labels
  c57 := pg_temp.mp_ensure_cat(c53, 'die-cut-stickers', 'Die-cut Stickers', 'Stickers cut to the exact shape of your logo or design.', 'Die-cut stickers are cut around the outline of your logo or artwork, creating eye-catching custom shapes. They are popular for giveaways, packaging and brand merchandise. We prepare a proof showing the cut line before printing so you can check the shape.', NULL, 3); -- offset-printing/stickers-labels/die-cut-stickers
  c58 := pg_temp.mp_ensure_cat(m_offset_printing, 'calendars', 'Calendars', 'Custom calendar printing in Lahore: wall, desk and pocket calendars with your branding.', 'Custom calendars keep your brand in front of customers every day of the year. Mix Print Design prints wall, desk and pocket calendars in Lahore for companies, banks, pharmaceutical firms, schools and shops across Pakistan.

Add your logo, products, contact details and photos to every month, and include important dates such as Islamic and national holidays. Calendars make popular corporate gifts at the start of the year and are a cost-effective way to promote your business.

Tell us the type, size and quantity, and share your photos or ask our designers to create the layout. You approve every page in the proof before we print.', NULL, 8); -- offset-printing/calendars
  c59 := pg_temp.mp_ensure_cat(c58, 'wall-calendars', 'Wall Calendars', 'Large wall calendars with monthly pages and your branding.', 'Wall calendars hang in offices, shops and homes for the whole year, keeping your brand visible every day. Use a page per month with photos of your products or projects. They make excellent New Year gifts for clients. Ask us about sizes and binding options.', NULL, 0); -- offset-printing/calendars/wall-calendars
  c60 := pg_temp.mp_ensure_cat(c58, 'desk-calendars', 'Desk Calendars', 'Standing desk calendars for office tables and counters.', 'Desk calendars stand on office desks and reception counters, where they are seen many times a day. They suit corporate gifting and promotional giveaways. Each page can carry your logo and contact details. We help you plan the layout and holidays.', NULL, 1); -- offset-printing/calendars/desk-calendars
  c61 := pg_temp.mp_ensure_cat(c58, 'pocket-calendars', 'Pocket Calendars', 'Card-sized pocket calendars that are cheap to give away in bulk.', 'Pocket calendars are the size of a business card, with a full year on one side and your branding on the other. They are inexpensive to print in large quantities and easy to hand out at counters and events. A useful, low-cost promotional item.', NULL, 2); -- offset-printing/calendars/pocket-calendars
  c62 := pg_temp.mp_ensure_cat(m_offset_printing, 'cards-invitations', 'Cards & Invitations', 'Wedding cards, invitations and greeting card printing in Lahore with premium finishes.', 'Beautiful cards and invitations set the tone for weddings, events and celebrations. Mix Print Design prints wedding cards, invitation cards, greeting cards and Eid cards in Lahore, with premium papers and finishes such as foil, embossing and lamination.

Families and event planners across Pakistan use our cards for mehndi, barat and walima invitations, while companies send greeting cards and Eid cards to clients and staff. Our designers can create a design in English, Urdu or both, matching your theme and colours.

Share your event details, wording and quantity, and we will prepare a proof for your approval. Matching envelopes can be printed too.', NULL, 9); -- offset-printing/cards-invitations
  c63 := pg_temp.mp_ensure_cat(c62, 'wedding-cards', 'Wedding Cards', 'Elegant wedding cards for mehndi, barat and walima in English and Urdu.', 'Wedding cards are designed to match your celebration, with elegant layouts in English, Urdu or both. Choose premium papers and finishes such as foil and embossing for a memorable invitation. We can print cards for each function and matching envelopes. Share your wording and theme for a proof.', NULL, 0); -- offset-printing/cards-invitations/wedding-cards
  c64 := pg_temp.mp_ensure_cat(c62, 'invitation-cards', 'Invitation Cards', 'Invitation cards for birthdays, corporate events, openings and ceremonies.', 'Invitation cards set the tone for birthdays, inaugurations, corporate dinners and school functions. We design and print cards in a style that suits your event, from formal to fun. Add RSVP details and maps as needed. Ask for a quote with your quantity.', NULL, 1); -- offset-printing/cards-invitations/invitation-cards
  c65 := pg_temp.mp_ensure_cat(c62, 'greeting-cards', 'Greeting Cards', 'Custom greeting cards for clients, staff and special occasions.', 'Custom greeting cards let businesses thank clients, welcome new customers and celebrate milestones with a personal touch. Print your own message and branding inside. They are a thoughtful alternative to generic cards. We can also print matching envelopes.', NULL, 2); -- offset-printing/cards-invitations/greeting-cards
  c66 := pg_temp.mp_ensure_cat(c62, 'eid-cards', 'Eid Cards', 'Branded Eid Mubarak cards for clients, staff and family.', 'Eid cards are a warm way to greet clients, staff and family during Eid ul Fitr and Eid ul Adha. We design cards with festive themes and your branding or family names. Order early before Eid to plan delivery. Ask for designs in English and Urdu.', NULL, 3); -- offset-printing/cards-invitations/eid-cards
  c67 := pg_temp.mp_ensure_cat(m_offset_printing, 'catalogues', 'Catalogues', 'Product catalogue printing in Lahore: saddle-stitched and perfect-bound catalogues.', 'A printed catalogue showcases your full product range in one professional book that buyers can keep and refer to. Mix Print Design prints catalogues in Lahore for manufacturers, exporters, fashion brands, furniture makers and distributors across Pakistan.

Choose saddle-stitched binding for slimmer catalogues or perfect binding with a flat spine for thicker books. Full-colour printing on quality art paper makes product photos look their best, and a laminated cover keeps the catalogue looking good with frequent use.

Send us your page count, size and quantity, or ask our designers to lay out your products and prices. You approve a full proof before printing.', NULL, 10); -- offset-printing/catalogues
  c68 := pg_temp.mp_ensure_cat(c67, 'saddle-stitched-catalogues', 'Saddle-stitched Catalogues', 'Stapled catalogues for slimmer product ranges and price lists.', 'Saddle-stitched catalogues are stapled through the spine, an economical choice for catalogues of up to around sixty pages. They open flat and are easy to mail and hand out at exhibitions. Page counts are in multiples of four. Ask us about paper and cover options.', NULL, 0); -- offset-printing/catalogues/saddle-stitched-catalogues
  c69 := pg_temp.mp_ensure_cat(c67, 'perfect-bound-catalogues', 'Perfect-bound Catalogues', 'Perfect-bound catalogues with a flat printed spine for larger page counts.', 'Perfect-bound catalogues have a glued flat spine, giving a book-like finish for larger page counts. The spine can carry your brand name so the catalogue stands out on shelves. Ideal for annual catalogues, look-books and export collections.', NULL, 1); -- offset-printing/catalogues/perfect-bound-catalogues
  c70 := pg_temp.mp_ensure_cat(m_offset_printing, 'packaging-boxes', 'Packaging & Boxes', 'Custom printed boxes and packaging in Lahore for products, e-commerce and food.', 'Custom packaging protects your products and turns every delivery into a branding opportunity. Mix Print Design prints product boxes, mailer boxes and food packaging in Lahore for brands, online sellers, bakeries and restaurants across Pakistan.

Choose printed card boxes for cosmetics, medicines and retail products, corrugated mailer boxes for e-commerce shipping, or food-safe boxes for sweets, bakery items and takeaway. Finishes such as lamination, spot UV and foil help premium products stand out.

Share your product dimensions, quantity and artwork, and we will suggest a box style and material. You approve a proof, and sample options can be discussed before a large order.', NULL, 11); -- offset-printing/packaging-boxes
  c71 := pg_temp.mp_ensure_cat(c70, 'product-boxes', 'Product Boxes', 'Printed card boxes for cosmetics, medicines and retail products.', 'Printed product boxes present your item professionally on shop shelves and protect it in transit. They are popular for cosmetics, perfumes, medicines, electronics accessories and gifts. Share your product size and we will suggest the right box style and card thickness.', NULL, 0); -- offset-printing/packaging-boxes/product-boxes
  c72 := pg_temp.mp_ensure_cat(c70, 'mailer-boxes', 'Mailer Boxes', 'Corrugated mailer boxes for e-commerce and subscription deliveries.', 'Mailer boxes are sturdy corrugated boxes that protect products during courier delivery and create a memorable unboxing experience. They suit online stores, subscription boxes and gift packs. Print outside only or inside and outside. Ask for a quote with your box size.', NULL, 1); -- offset-printing/packaging-boxes/mailer-boxes
  c73 := pg_temp.mp_ensure_cat(c70, 'food-packaging', 'Food Packaging', 'Boxes for sweets, bakery items and takeaway food.', 'Food packaging includes boxes for sweets, cakes, bakery items, pizzas and takeaway meals. Branded packaging helps customers remember your shop. Tell us the food type and size so we can recommend suitable materials and styles.', NULL, 2); -- offset-printing/packaging-boxes/food-packaging
  c74 := pg_temp.mp_ensure_cat(m_offset_printing, 'posters', 'Posters', 'Poster printing in Lahore in A3 and A2 sizes for promotions, events and education.', 'Posters grab attention on walls, notice boards and shop windows. Mix Print Design prints posters in Lahore for sales, events, admissions, health awareness campaigns and educational displays across Pakistan.

Choose A3 for counters and notice boards or A2 for larger displays. Glossy paper makes images vibrant, while matte paper reduces glare under shop lights. For outdoor or very large formats, see our digital printing services such as flex and vinyl.

Posters are widely used for school admissions, health awareness drives, product launches, property projects and seasonal sales. For the best result, use large, readable headlines, a single strong image and your phone number or WhatsApp in a clear spot near the bottom.

Send us your artwork or ask our designers to create a clear, eye-catching layout. You approve the proof before we print.', NULL, 12); -- offset-printing/posters
  c75 := pg_temp.mp_ensure_cat(c74, 'a3-posters', 'A3 Posters', 'A3 posters for notice boards, counters and shop windows.', 'A3 posters are a practical size for notice boards, counters, clinics and shop windows. They are affordable in bulk for campaigns and events. Bold headlines and clear images help them work from a distance. Ask for a quote by quantity.', NULL, 0); -- offset-printing/posters/a3-posters
  c76 := pg_temp.mp_ensure_cat(c74, 'a2-posters', 'A2 Posters', 'Larger A2 posters for high-impact displays and events.', 'A2 posters give double the space of A3 for high-impact displays in malls, schools, exhibitions and events. Large images and short messages work best. Choose gloss or matte paper. Share your design for a proof.', NULL, 1); -- offset-printing/posters/a2-posters
  c77 := pg_temp.mp_ensure_cat(m_offset_printing, 'paper-bags', 'Paper Bags', 'Printed paper shopping bags in Lahore for boutiques, bakeries and retail stores.', 'Printed paper bags carry your brand out of the shop and around the city. Mix Print Design prints paper shopping bags in Lahore for boutiques, bakeries, pharmacies, gift shops and retail brands across Pakistan.

Choose white or kraft paper, different sizes and handle styles, and add your logo, colours and social media handles. Paper bags are an attractive, eco-friendlier alternative to plastic and make your products feel more premium.

Bags can be made in small sizes for jewellery and cosmetics, medium sizes for pharmacies and bakeries, and larger sizes for clothing and gifts. Printing your website or Instagram handle on the side panel turns every bag into a small advertisement on the street.

Tell us the size, quantity and design, and we will advise on paper thickness and handles. You approve the proof before printing.', NULL, 13); -- offset-printing/paper-bags
  c78 := pg_temp.mp_ensure_cat(c77, 'kraft-paper-bags', 'Kraft Paper Bags', 'Natural kraft paper bags with a rustic, eco-friendly look.', 'Kraft paper bags have a natural brown finish that suits organic food stores, bakeries, cafés and handmade brands. They print well with dark inks and simple logos. Choose a size and handle type that fits your products.', NULL, 0); -- offset-printing/paper-bags/kraft-paper-bags
  c79 := pg_temp.mp_ensure_cat(c77, 'white-paper-bags', 'White Paper Bags', 'White paper bags that show full-colour branding brightly.', 'White paper bags show full-colour designs brightly, making them ideal for boutiques, gift shops and cosmetics brands. Lamination can add strength and a premium feel. Ask us about sizes and handle options.', NULL, 1); -- offset-printing/paper-bags/white-paper-bags
  c80 := pg_temp.mp_ensure_cat(m_offset_printing, 'notepads-diaries', 'Notepads & Diaries', 'Branded notepads, prescription pads and diaries printed in Lahore.', 'Branded notepads and diaries are used every day, keeping your name in front of clients and staff. Mix Print Design prints notepads, prescription pads, writing pads and custom diaries in Lahore for offices, doctors, hotels, schools and corporate gifting across Pakistan.

Notepads can be glued at the top for easy tear-off pages, with your logo and contact details on every sheet. Doctors use printed prescription pads, hotels place notepads in rooms, and companies give diaries as New Year gifts.

Tell us the size, number of pages and quantity, and share your design or ask our designers for help. You approve the proof before printing.', NULL, 14); -- offset-printing/notepads-diaries
  c81 := pg_temp.mp_ensure_cat(c80, 'notepads', 'Notepads', 'Tear-off notepads with your logo on every page.', 'Branded notepads keep your logo on every page, ideal for offices, hotels, events and giveaways. Pages are glued at the top for clean tear-off. Choose the size and page count that suits your use. Ask for a quote by quantity.', NULL, 0); -- offset-printing/notepads-diaries/notepads
  c82 := pg_temp.mp_ensure_cat(c80, 'prescription-pads', 'Prescription Pads', 'Printed prescription pads for doctors, clinics and hospitals.', 'Prescription pads carry the doctor''s name, qualifications, clinic address and timings at the top of each sheet. Clinics and hospitals use them daily, so clear layout and good paper matter. Share your details and we will prepare a proof.', NULL, 1); -- offset-printing/notepads-diaries/prescription-pads
  c83 := pg_temp.mp_ensure_cat(c80, 'custom-diaries', 'Custom Diaries', 'Branded diaries for corporate gifting and staff.', 'Custom diaries make practical corporate gifts and staff giveaways, especially at the start of the year. Add your logo on the cover and branded pages inside. Ask us about cover materials, sizes and quantities.', NULL, 2); -- offset-printing/notepads-diaries/custom-diaries
  c84 := pg_temp.mp_ensure_cat(m_offset_printing, 'menu-cards', 'Menu Cards', 'Restaurant menu card printing in Lahore: laminated, folded and takeaway menus.', 'A clear, attractive menu helps customers choose and order more. Mix Print Design prints menu cards in Lahore for restaurants, cafés, food courts, bakeries and caterers across Pakistan.

Choose laminated menus that resist spills and frequent handling for dine-in tables, or folded and flyer-style takeaway menus for delivery orders and counters. Our designers can organise your dishes and prices into easy-to-read sections and add appetising photos.

Good menus group dishes into clear sections, show prices in a consistent column, and use photos only where they help sell signature items. We can also print matching table tents, flyers and delivery stickers so your branding stays consistent.

Send us your menu items and prices, or your current menu to refresh. You approve the proof before printing, and reprints are easy when prices change.', NULL, 15); -- offset-printing/menu-cards
  c85 := pg_temp.mp_ensure_cat(c84, 'laminated-menu-cards', 'Laminated Menu Cards', 'Durable laminated menus for dine-in tables.', 'Laminated menu cards resist spills, stains and frequent handling, keeping them clean and readable for longer. They suit restaurants, cafés and dhabas with dine-in seating. Choose single sheets or folded menus. Share your items for a proof.', NULL, 0); -- offset-printing/menu-cards/laminated-menu-cards
  c86 := pg_temp.mp_ensure_cat(c84, 'takeaway-menus', 'Takeaway Menus', 'Folded takeaway menus for delivery orders and counters.', 'Takeaway menus are folded or flyer-style menus customers take home or receive with delivery orders. They include your phone numbers and delivery details to encourage repeat orders. Affordable in large quantities.', NULL, 1); -- offset-printing/menu-cards/takeaway-menus
  c87 := pg_temp.mp_ensure_cat(m_offset_printing, 'certificates', 'Certificates', 'Certificate printing in Lahore for schools, training institutes and events.', 'Certificates recognise achievement and should look official and memorable. Mix Print Design prints certificates in Lahore for schools, colleges, universities, training institutes, sports events and companies across Pakistan.

We print on quality paper or card with security-style borders, your logo and signatures, and can add gold foil seals or embossed details for a formal finish. Certificates can be printed with each recipient''s name for a personal touch.

Common uses include school result and merit certificates, course completion certificates for training institutes, sports participation certificates, and employee of the month or long-service awards. Clear fonts and enough space for signatures and dates make certificates look professional.

Share your certificate design or ask our designers to create one. You approve the proof before printing, and matching certificate folders are available.', NULL, 16); -- offset-printing/certificates
  c88 := pg_temp.mp_ensure_cat(m_offset_printing, 'hang-tags', 'Hang Tags', 'Clothing hang tags and price tags printed in Lahore for fashion brands.', 'Hang tags add a finishing touch to clothing, accessories and gifts while carrying your brand, sizes and prices. Mix Print Design prints hang tags in Lahore for fashion brands, boutiques, shoe makers and gift shops across Pakistan.

Choose thick card or kraft board, round corners and punched holes, with finishes such as spot UV, foil or embossing for premium labels. Tags can include barcodes, care instructions and your social media handles.

Tags can be printed on both sides, with branding on the front and size, price or care details on the back. Many brands add a short brand story or a QR code that links to their online shop, helping turn first-time buyers into repeat customers.

Tell us the size, quantity and finish, and send your design or ask our designers for help. You approve the proof before printing.', NULL, 17); -- offset-printing/hang-tags
  c89 := pg_temp.mp_ensure_cat(m_digital_printing, 'flex-printing', 'Flex Printing', 'Flex printing in Lahore on China flex, HD Star flex, Star flex and Korean Star flex, priced per sq. ft.', 'Flex printing is the most popular choice for banners, shop boards, event backdrops and roadside advertising in Pakistan. Mix Print Design prints flex banners in Lahore on several qualities of flex, so you can balance price, sharpness and durability for each job.

China flex is the economical option for short-term promotions and events. Star flex and HD Star flex give sharper prints and better colour for longer use, while Korean Star flex is a premium material for signs that must look good outdoors for a long time. Flex is priced per square foot and can be finished with eyelets, pole pockets or frames.

Tell us the size, quantity and where the banner will be used, and we will recommend the right flex and send a quote.', 'per sq. ft', 0); -- digital-printing/flex-printing
  c90 := pg_temp.mp_ensure_cat(c89, 'china-flex', 'China Flex', 'Economical China flex printing for short-term banners and events.', 'China flex is the most economical flex material, ideal for short-term promotions, event banners, political and religious gatherings and temporary signage. It prints bright colours at a low cost per square foot. For signs that must last longer outdoors, consider Star or Korean flex. Ask for a quote with your size.', 'per sq. ft', 0); -- digital-printing/flex-printing/china-flex
  c91 := pg_temp.mp_ensure_cat(c89, 'hd-star-flex', 'HD Star Flex', 'High-definition Star flex for sharper images and stronger colours.', 'HD Star flex is printed at higher resolution for sharper text, smoother gradients and stronger colours. It suits shop boards, exhibition backdrops and banners viewed from close range. A good balance of quality and price for long-term indoor and outdoor use. Priced per square foot.', 'per sq. ft', 1); -- digital-printing/flex-printing/hd-star-flex
  c92 := pg_temp.mp_ensure_cat(c89, 'star-flex', 'Star Flex', 'Durable Star flex for shop signs and long-lasting banners.', 'Star flex is a stronger, better-quality flex than China flex, with improved colour and durability outdoors. It is a popular choice for shop front boards, rooftop signs and banners that stay up for months. Ask us to compare it with HD and Korean Star flex for your budget.', 'per sq. ft', 2); -- digital-printing/flex-printing/star-flex
  c93 := pg_temp.mp_ensure_cat(c89, 'korean-star-flex', 'Korean Star Flex', 'Premium Korean Star flex for long-lasting outdoor signs.', 'Korean Star flex is a premium flex material known for durability and rich colour, making it a good choice for permanent outdoor signs and backlit boards. It holds up well to sun and weather over long periods. Recommended when quality and lifespan matter most. Priced per square foot.', 'per sq. ft', 3); -- digital-printing/flex-printing/korean-star-flex
  c94 := pg_temp.mp_ensure_cat(m_digital_printing, 'panaflex', 'Panaflex', 'Panaflex printing in Lahore for sign boards and large outdoor displays.', 'Panaflex is the familiar term in Pakistan for printed flex sign boards and large outdoor displays. Mix Print Design prints panaflex in Lahore for shop fronts, plazas, petrol pumps, schools and hospitals, in front-lit and backlit versions.

Front-lit panaflex is lit by spotlights from the front, while backlit panaflex uses translucent media with lights behind for an even glow at night. We print your design, stretch it on a frame and can coordinate installation for your location.

Send us the size and location, or a photo of the site, and we will recommend the right material and quote per square foot. You approve the design proof before printing.', 'per sq. ft', 1); -- digital-printing/panaflex
  c95 := pg_temp.mp_ensure_cat(m_digital_printing, 'vinyl-one-way-vision', 'Vinyl / One-way Vision', 'Vinyl printing and one-way vision for windows, walls, vehicles and glass in Lahore.', 'Printed vinyl sticks to glass, walls, boards and vehicles to turn plain surfaces into branding. Mix Print Design prints vinyl and one-way vision in Lahore for shop windows, offices, clinics, showrooms and vehicles across Pakistan.

Standard vinyl is used for wall graphics, glass decoration, product displays and signage. One-way vision is a perforated vinyl that shows your graphics on the outside while people inside can still see out, making it ideal for shop windows and vehicle rear glass.

Tell us the surface, size and whether the graphics are for indoors or outdoors. We will recommend the right vinyl, prepare the artwork to size and quote per square foot.', 'per sq. ft', 2); -- digital-printing/vinyl-one-way-vision
  c96 := pg_temp.mp_ensure_cat(c95, 'vinyl-printing', 'Vinyl Printing', 'Full-colour vinyl for walls, glass, boards and displays.', 'Printed vinyl turns walls, glass partitions, counters and boards into branded surfaces. It is available in gloss or matte finishes and can be cut to shape. Popular for offices, clinics, retail displays and events. Priced per square foot.', 'per sq. ft', 0); -- digital-printing/vinyl-one-way-vision/vinyl-printing
  c97 := pg_temp.mp_ensure_cat(c95, 'one-way-vision', 'One-way Vision', 'Perforated one-way vision for shop windows and vehicle glass.', 'One-way vision vinyl shows your graphics from the outside while keeping the view clear from the inside. It is widely used on shop windows, office glass and vehicle rear windows for advertising without blocking light. Priced per square foot.', 'per sq. ft', 1); -- digital-printing/vinyl-one-way-vision/one-way-vision
  c98 := pg_temp.mp_ensure_cat(m_digital_printing, 'canvas-printing', 'Canvas Printing', 'Canvas printing in Lahore for photos, art and décor, with or without frames.', 'Canvas prints turn photos and artwork into décor for homes, offices, restaurants and hotels. Mix Print Design prints on quality canvas in Lahore, either as rolled prints or stretched on frames ready to hang.

Families print portraits and wedding photos, businesses print brand imagery and Islamic calligraphy, and interior designers order canvas art for projects across Pakistan. Canvas gives a textured, gallery-style look that suits both modern and classic interiors.

High-resolution photos give the sharpest canvas prints, so we check every image before printing and tell you if a smaller size will look better. Popular sizes range from small gift prints to large statement pieces for living rooms and office reception areas.

Send us your image and preferred size. We will check the resolution so the print looks sharp, and send you a proof before printing.', NULL, 3); -- digital-printing/canvas-printing
  c99 := pg_temp.mp_ensure_cat(c98, 'canvas-prints', 'Canvas Prints', 'Rolled canvas prints for framing or mounting.', 'Rolled canvas prints are printed on textured canvas without a frame, ready for you to frame or mount. They suit artists, photographers and interior projects. We check image resolution before printing to keep the result sharp.', NULL, 0); -- digital-printing/canvas-printing/canvas-prints
  c100 := pg_temp.mp_ensure_cat(c98, 'framed-canvas', 'Framed Canvas', 'Canvas stretched on frames, ready to hang.', 'Framed canvas is stretched over a wooden frame and ready to hang on the wall. It is ideal for portraits, calligraphy, office décor and gifts. Choose the size that suits your wall and we will prepare a proof.', NULL, 1); -- digital-printing/canvas-printing/framed-canvas
  c101 := pg_temp.mp_ensure_cat(m_digital_printing, 'standees-roll-up-banners', 'Standees / Roll-up Banners', 'Roll-up standees and X-banners printed in Lahore for exhibitions, events and shops.', 'Standees are portable banners that set up in seconds at exhibitions, seminars, bank branches, malls and shop entrances. Mix Print Design prints roll-up standees and X-banners in Lahore with the printed graphic, stand and carry bag.

Roll-up standees retract into their base for easy transport and are ideal for events and frequent use, while X-banners are a lighter, economical option. Standees help brands across Pakistan promote launches, offers and services wherever customers gather.

Keep standee designs simple: your logo at the top, one clear message in the middle, and contact details near eye level. Avoid placing important text at the very bottom, where it can be hidden by the base or by people standing in front.

Send us your artwork or ask our designers to create a design that reads well from a distance. You approve the proof before printing.', NULL, 4); -- digital-printing/standees-roll-up-banners
  c102 := pg_temp.mp_ensure_cat(c101, 'roll-up-standee', 'Roll-up Standee', 'Retractable roll-up standees with base and carry bag.', 'Roll-up standees retract into an aluminium base for quick setup and easy carrying. They are perfect for exhibitions, seminars, reception areas and in-store promotions. The graphic can be replaced later on the same stand. Ask for a quote with your preferred size.', NULL, 0); -- digital-printing/standees-roll-up-banners/roll-up-standee
  c103 := pg_temp.mp_ensure_cat(c101, 'x-banner', 'X-Banner', 'Lightweight, economical X-banners for events and shops.', 'X-banners use a lightweight X-shaped stand, making them the most economical portable banner. They suit short promotions, events and shop entrances. Easy to assemble and transport.', NULL, 1); -- digital-printing/standees-roll-up-banners/x-banner
  c104 := pg_temp.mp_ensure_cat(c101, 'backdrop-stands', 'Backdrop Stands', 'Large backdrop banners for stages, photo walls and press events.', 'Backdrop stands hold large printed banners behind stages, reception desks and photo areas at events, launches and press conferences. They create a branded background for photos and videos. Tell us the width and height you need.', NULL, 2); -- digital-printing/standees-roll-up-banners/backdrop-stands
  c105 := pg_temp.mp_ensure_cat(m_digital_printing, 'backlit-film', 'Backlit Film', 'Backlit film printing in Lahore for light boxes and illuminated displays.', 'Backlit film is a translucent material printed for light boxes and illuminated displays, giving rich, even colour when lit from behind. Mix Print Design prints backlit film in Lahore for restaurant menu boards, pharmacies, malls, airports and showroom displays.

Compared with standard media, backlit film shows sharper detail and deeper colours, making product and food photos look appealing. It is ideal for indoor light boxes where viewers are close to the display.

Backlit film is often used together with aluminium light box frames, which can be single or double-sided. Replacing only the printed film is an affordable way to update menus, prices and seasonal promotions without changing the whole display.

Send us the light box size and your artwork. We will prepare the file at the right resolution and quote per square foot.', 'per sq. ft', 5); -- digital-printing/backlit-film
  c106 := pg_temp.mp_ensure_cat(m_digital_printing, 'wall-graphics-wallpapers', 'Wall Graphics & Wallpapers', 'Custom wall graphics and printed wallpapers for offices, cafés and homes in Lahore.', 'Custom wall graphics and printed wallpapers transform plain walls into branded or decorative features. Mix Print Design prints wall graphics in Lahore for offices, cafés, restaurants, schools, clinics and homes across Pakistan.

Show your company values in the office, add a mural in a restaurant, or create a feature wall at home with your own image. Materials are chosen for the wall surface and how long the graphic needs to last.

Popular ideas include company timelines and values in offices, food photography and quotes in restaurants, learning themes in schools and nurseries, and calming scenery in clinics and waiting rooms. Removable materials are available for rented spaces.

Send us the wall measurements and a photo, and our designers can prepare artwork to fit. We quote per square foot and send a proof before printing.', 'per sq. ft', 6); -- digital-printing/wall-graphics-wallpapers
  c107 := pg_temp.mp_ensure_cat(m_digital_printing, 'vehicle-branding', 'Vehicle Branding', 'Vehicle branding and car wraps in Lahore for delivery vans, cars and bikes.', 'Vehicle branding turns cars, vans, rickshaws and delivery bikes into moving advertisements. Mix Print Design prints vehicle graphics in Lahore for delivery services, schools, companies and campaigns across Pakistan.

Choose partial graphics such as logos and contact details on doors, or larger wraps for maximum impact, with one-way vision on rear windows. Durable vinyl keeps graphics looking good on the road.

Good vehicle graphics are simple and readable at a glance: a large logo, the service you offer and one phone number. Fleet branding keeps every vehicle consistent, which builds recognition as your vans and bikes move around the city.

Tell us the vehicle model and the coverage you want, and our designers will prepare a layout to fit. We send a proof and quote before printing.', 'per sq. ft', 7); -- digital-printing/vehicle-branding
  c108 := pg_temp.mp_ensure_cat(m_digital_printing, 'fabric-sublimation-banners', 'Fabric & Sublimation Banners', 'Fabric banners, flags and sublimation prints for events and exhibitions.', 'Fabric banners and flags printed by sublimation have bright, washable colours and a premium, glare-free look. Mix Print Design prints fabric banners in Lahore for exhibitions, sports events, schools, conferences and brand activations across Pakistan.

Fabric is light to carry, folds without creasing badly and looks great under event lighting. Use it for backdrops, table covers, flags and hanging banners.

Sublimation dyes the ink into the fabric rather than printing on top, so colours stay vivid and do not crack or peel. Fabric banners can be hemmed, fitted with pole pockets or eyelets, or sewn into tension-fabric frames for a smooth, wrinkle-free display.

Share the size and use, and we will recommend a fabric and finishing. You approve the proof before printing.', 'per sq. ft', 8); -- digital-printing/fabric-sublimation-banners
  c109 := pg_temp.mp_ensure_cat(m_customized_printing, 'pens', 'Pens', 'Printed and engraved pens with your logo for offices, events and giveaways.', 'Branded pens are one of the most useful promotional items, used every day at desks, counters and meetings. Mix Print Design prints and engraves pens in Lahore with your logo, name or message, for corporate giveaways, conferences, schools and hotels across Pakistan.

Choose from everyday plastic pens for large giveaways or metal pens with laser engraving for executive gifts. A clear logo and contact details keep your brand in front of customers long after the event.

Tell us the quantity and the style you prefer, and share your logo. We will suggest suitable options and send a proof before production.', NULL, 0); -- customized-printing/pens
  c110 := pg_temp.mp_ensure_cat(m_customized_printing, 'keychains', 'Keychains', 'Custom keychains in acrylic, metal and rubber, printed or engraved in Lahore.', 'Custom keychains are small, low-cost gifts that people carry every day. Mix Print Design makes printed and engraved keychains in Lahore for businesses, real-estate projects, car dealers, schools and events.

Choose acrylic keychains with full-colour prints, metal keychains with laser engraving, or custom shapes that match your logo. They make great giveaways, souvenirs and personalised gifts with names or photos.

Popular uses include real-estate and car-dealer giveaways, school and university souvenirs, wedding favours and personalised gifts with names or photos. Bulk orders keep the cost per piece low, while individual names can be added for a personal touch.

Share your design, quantity and preferred material, and we will send a proof and quote.', NULL, 1); -- customized-printing/keychains
  c111 := pg_temp.mp_ensure_cat(m_customized_printing, 'mugs', 'Mugs', 'Custom printed mugs in Lahore with logos, photos and messages.', 'Printed mugs are a favourite gift and a long-lasting branding item for offices and cafés. Mix Print Design prints custom mugs in Lahore with your logo, photo or message, for corporate gifts, staff appreciation, birthdays, weddings and Eid.

Choose classic white mugs, coloured inner mugs or magic mugs that reveal the design when filled with a hot drink. Each mug can carry a different name or photo for a personal touch.

Mugs are a reliable choice for corporate gifts because they are used daily on desks and in homes. They also make popular personalised gifts for birthdays, Mother''s and Father''s Day and anniversaries, and can be packed in printed gift boxes.

Send us your images and quantity, and we will prepare a proof before printing.', NULL, 2); -- customized-printing/mugs
  c112 := pg_temp.mp_ensure_cat(m_customized_printing, 'photo-frames', 'Photo Frames', 'Personalised photo frames and printed frames for gifts and décor.', 'Personalised photo frames turn special memories into lasting gifts. Mix Print Design prints photo frames in Lahore for birthdays, weddings, anniversaries, graduations and corporate recognition.

Choose frames with your printed photo and message, or acrylic and wooden frames with engraved details. They are thoughtful gifts for family and friends, and also suit award ceremonies and staff recognition.

Photo frames are popular for wedding and anniversary gifts, baby milestones, graduation photos and memorial tributes. Businesses also use framed prints for awards, certificates and wall displays of their team or achievements.

Send us your photo and preferred size, and we will check the image quality and send a proof before printing.', NULL, 3); -- customized-printing/photo-frames
  c113 := pg_temp.mp_ensure_cat(m_customized_printing, 't-shirts', 'T-Shirts', 'Custom T-shirt printing in Lahore for teams, events, brands and schools.', 'Custom T-shirts unite teams and promote brands at events, campaigns and sports days. Mix Print Design prints T-shirts in Lahore with your logo, slogan or artwork, for companies, schools, universities, clubs and events across Pakistan.

Choose the shirt colour, sizes and print positions such as front, back and sleeves. Printing methods are chosen according to your design and quantity to keep colours bright and durable.

T-shirts are popular for company events and family days, school sports and trips, marathons and charity walks, product launches and university societies. Including the size breakdown with your order helps us plan production and avoid shortages.

Tell us the quantity by size, the colours and your design, and we will send a proof and quote before production.', NULL, 4); -- customized-printing/t-shirts
  c114 := pg_temp.mp_ensure_cat(m_customized_printing, 'safety-jackets', 'Safety Jackets', 'Printed high-visibility safety jackets with company logos and names.', 'Printed safety jackets keep workers visible and identify your company on construction sites, factories, warehouses, events and traffic duties. Mix Print Design prints high-visibility safety jackets in Lahore with your logo, company name and job titles.

Clear branding helps visitors identify staff, improves safety and gives your team a professional look. Jackets can be printed on the front, back or both.

They are commonly used by construction and engineering firms, security companies, event management teams, parking staff and delivery services. Adding a role such as Supervisor or Security on the back helps people find the right person quickly.

Share your logo, quantity and sizes, and we will send a proof and quote.', NULL, 5); -- customized-printing/safety-jackets
  c115 := pg_temp.mp_ensure_cat(m_customized_printing, 'caps', 'Caps', 'Custom printed and embroidered caps for teams, events and promotions.', 'Custom caps are popular for promotional campaigns, sports teams, staff uniforms and events. Mix Print Design prints caps in Lahore with your logo or slogan for companies, clubs and schools across Pakistan.

Choose cap colours and the print or embroidery position on the front, side or back. Caps make practical giveaways that keep your brand visible outdoors.

Caps work well for outdoor promotions, cricket and football teams, school trips, political and community campaigns, and staff at petrol pumps, delivery services and events. A simple logo usually gives the cleanest result on the curved front panel.

Tell us the quantity, colours and your design, and we will send a proof and quote before production.', NULL, 6); -- customized-printing/caps
  c116 := pg_temp.mp_ensure_cat(m_customized_printing, 'laser-printing', 'Laser Printing', 'Laser cutting and laser printing for custom shapes, signs and gifts in Lahore.', 'Laser printing and laser cutting create precise shapes and detailed designs in materials such as acrylic, wood and card. Mix Print Design offers laser services in Lahore for signage parts, décor, invitations, gifts and branded items.

Laser cutting makes intricate patterns, lettering and custom shapes that are difficult to produce by hand, with clean edges and consistent results across many pieces.

Popular laser-cut items include acrylic letters for signs, decorative wall pieces, wedding and event décor, invitation card inserts, cake toppers, display stands and custom packaging inserts. Vector artwork gives the cleanest cut lines.

Send us your design or idea, the material and quantity, and we will advise on what is possible and send a quote.', NULL, 7); -- customized-printing/laser-printing
  c117 := pg_temp.mp_ensure_cat(m_customized_printing, 'laser-marking-engraving', 'Laser Marking / Engraving', 'Laser engraving and marking on metal, wood and acrylic in Lahore.', 'Laser engraving marks names, logos and serial numbers permanently on metal, wood, acrylic and other materials. Mix Print Design offers laser marking and engraving in Lahore for corporate gifts, pens, keychains, plaques, tools and equipment.

Engraving gives a refined, permanent finish that does not wear off like ink, making it ideal for executive gifts, awards and product identification.

Typical engraved items include metal pens, keychains, power banks, diaries, wooden and acrylic plaques, trophies, tools and machine parts with serial numbers. Engraving each item with a different name is a popular way to personalise corporate gifts.

Tell us the item, material and design, and we will send a proof and quote.', NULL, 8); -- customized-printing/laser-marking-engraving
  c118 := pg_temp.mp_ensure_cat(m_customized_printing, 'acrylic-name-plates', 'Acrylic Name Plates', 'Acrylic name plates for homes, offices and doors in Lahore.', 'Acrylic name plates give homes, offices and clinics a clean, modern nameplate. Mix Print Design makes acrylic name plates in Lahore for house gates, office doors, desks and reception counters.

Choose clear, frosted or coloured acrylic with printed, cut or engraved lettering, and mount it with stand-off fittings for a floating effect. Urdu and English lettering are both possible.

Popular styles include house name plates with Urdu and English names, doctor and lawyer office plates with qualifications, company reception signs and desk name plates. Outdoor plates can be made with UV-resistant printing and secure wall fittings.

Share the name, size and style you want, and we will send a design proof before production.', NULL, 9); -- customized-printing/acrylic-name-plates
  c119 := pg_temp.mp_ensure_cat(m_customized_printing, 'small-acrylic-signs-designs', 'Small Acrylic Signs & Designs', 'Small acrylic signs, table tents, stands and décor pieces.', 'Small acrylic signs and designs are useful for counters, desks, events and décor. Mix Print Design makes acrylic table signs, QR code stands, direction signs, menu holders, cake toppers and decorative pieces in Lahore.

Acrylic looks clean and modern, is easy to wipe and can be printed, cut or engraved. Small pieces are ideal for restaurants, clinics, shops, weddings and events.

QR code stands for payments and menus, Wi-Fi signs, reserved table signs, office door signs and wedding welcome signs are among the most requested small acrylic pieces. Printing on the back of clear acrylic protects the design from scratches.

Tell us what you need, the size and quantity, and we will suggest a design and send a quote.', NULL, 10); -- customized-printing/small-acrylic-signs-designs
  c120 := pg_temp.mp_ensure_cat(m_customized_printing, 'shields-awards', 'Shields / Awards', 'Custom shields, trophies and awards in Lahore for schools and companies.', 'Custom shields and awards recognise achievement at schools, universities, sports events and corporate ceremonies. Mix Print Design makes shields and awards in Lahore in wood, acrylic and metal, with printed or engraved logos, names and messages.

Each award can be personalised with the winner''s name and achievement, and designs can match your event theme. Ordering in good time before your ceremony helps us plan production.

Common orders include school annual result shields, sports trophies and medals, employee recognition awards, long-service plaques and appreciation shields for guests and speakers. Each piece can be presented in a box for a more formal ceremony.

Share the number of awards, names and your design ideas, and we will send a proof and quote.', NULL, 11); -- customized-printing/shields-awards
END $mig$;

-- ─── Data: copy the old Services hierarchy into the shared tree ───
-- ServiceCategory → main service, ServiceSubtype → category, ServiceQuality → sub-category.
-- Products linked to a sub-type or quality move to the matching category. The old tables are
-- left in place (unused) so no data is lost; they can be dropped in a later cleanup.
DO $svc$
DECLARE
  r record;
  v_dst text;
  v_parent text;
BEGIN
  CREATE TEMP TABLE mp_svc_map (src text PRIMARY KEY, dst text NOT NULL) ON COMMIT DROP;

  FOR r IN SELECT * FROM "ServiceCategory" ORDER BY "sortOrder" LOOP
    v_dst := CASE r.id
      WHEN 'svc_board_maker' THEN (SELECT id FROM "Category" WHERE "parentId" IS NULL AND slug = 'board-maker')
      WHEN 'svc_offset' THEN (SELECT id FROM "Category" WHERE "parentId" IS NULL AND slug = 'offset-printing')
      WHEN 'svc_digital' THEN (SELECT id FROM "Category" WHERE "parentId" IS NULL AND slug = 'digital-printing')
      ELSE pg_temp.mp_ensure_cat(NULL, r.slug, r.title, r."shortDescription", NULL, NULL, 10 + r."sortOrder")
    END;
    INSERT INTO mp_svc_map VALUES (r.id, v_dst);
    UPDATE "Category" SET "imageUrl" = r."imageUrl", "imageKey" = r."imageKey"
      WHERE id = v_dst AND "imageUrl" IS NULL AND r."imageUrl" IS NOT NULL;
  END LOOP;

  FOR r IN SELECT * FROM "ServiceSubtype" ORDER BY "sortOrder" LOOP
    v_parent := (SELECT dst FROM mp_svc_map WHERE src = r."categoryId");
    CONTINUE WHEN v_parent IS NULL;
    v_dst := CASE r.id
      WHEN 'svc_board_backlit' THEN (SELECT id FROM "Category" WHERE "parentId" = v_parent AND slug = 'backlit-sign-board')
      WHEN 'svc_board_frontlit' THEN (SELECT id FROM "Category" WHERE "parentId" = v_parent AND slug = 'front-lit-sign-board')
      WHEN 'svc_board_3d' THEN (SELECT id FROM "Category" WHERE "parentId" = v_parent AND slug = '3d-sign-board')
      ELSE pg_temp.mp_ensure_cat(v_parent, r.slug, r.title, r."shortDescription", NULL, NULL, 50 + r."sortOrder")
    END;
    CONTINUE WHEN v_dst IS NULL;
    INSERT INTO mp_svc_map VALUES (r.id, v_dst);
    UPDATE "Category" SET "imageUrl" = r."imageUrl", "imageKey" = r."imageKey"
      WHERE id = v_dst AND "imageUrl" IS NULL AND r."imageUrl" IS NOT NULL;
    UPDATE "Category" SET "isVisible" = false WHERE id = v_dst AND NOT r."isVisible" AND content IS NULL;
  END LOOP;

  FOR r IN SELECT * FROM "ServiceQuality" ORDER BY "sortOrder" LOOP
    -- Skip the example qualities that were only ever demo data.
    CONTINUE WHEN (r."subtypeId", r.slug, r."shortDescription") IN (
      ('svc_board_backlit', 'standard', 'Economical backlit flex for everyday shop signs.'),
      ('svc_board_backlit', 'premium', 'Brighter, more even light with premium translucent media.'),
      ('svc_board_frontlit', 'standard', 'Durable front-lit flex with lights mounted above.'),
      ('svc_board_frontlit', 'premium', 'Heavier media and sharper print for long-lasting signs.'),
      ('svc_board_3d', 'acrylic', 'Glossy acrylic letters with optional LED lighting.'),
      ('svc_board_3d', 'steel', 'Brushed or gold steel letters for a premium finish.'),
      ('svc_board_3d', 'pvc', 'Lightweight, budget-friendly raised letters.')
    );
    v_parent := (SELECT dst FROM mp_svc_map WHERE src = r."subtypeId");
    CONTINUE WHEN v_parent IS NULL;
    v_dst := pg_temp.mp_ensure_cat(v_parent, r.slug, r.title, r."shortDescription", NULL, NULL, 50 + r."sortOrder");
    INSERT INTO mp_svc_map VALUES (r.id, v_dst) ON CONFLICT DO NOTHING;
    UPDATE "Category" SET "imageUrl" = r."imageUrl", "imageKey" = r."imageKey"
      WHERE id = v_dst AND "imageUrl" IS NULL AND r."imageUrl" IS NOT NULL;
    UPDATE "Category" SET "isVisible" = false WHERE id = v_dst AND NOT r."isVisible" AND content IS NULL;
  END LOOP;

  -- Products placed under a quality or sub-type now belong to that category.
  UPDATE "Product" p SET "categoryId" = m.dst FROM mp_svc_map m WHERE p."serviceQualityId" = m.src;
  UPDATE "Product" p SET "categoryId" = m.dst FROM mp_svc_map m
    WHERE p."serviceQualityId" IS NULL AND p."serviceSubtypeId" = m.src;
END $svc$;
